    *   Does it have refresh tokens? Yes.
    *   Does it have rate limiting? Yes.This example provides a complete implementation in a single file. For production, you would move secrets to a `.env` file and use a database instead of an in-memory array to store refresh tokens.

```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');

const app = express();
app.use(express.json());

const ACCESS_TOKEN_SECRET = 'access_secret_123';
const REFRESH_TOKEN_SECRET = 'refresh_secret_456';

// Mock database for refresh tokens
let refreshTokens = [];

// 1. Rate Limiting: Max 100 requests per 15 minutes
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, 
  max: 100, 
  message: 'Too many requests, please try again later.'
});
app.use(limiter);

// Middleware to verify Access Token
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.sendStatus(401);

  jwt.verify(token, ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) return res.status(403).json({ message: 'Token expired or invalid' });
    req.user = user;
    next();
  });
};

// Route: Login (Generates Access and Refresh Tokens)
app.post('/login', (req, res) => {
  const { username } = req.body; // In real app, verify password here
  if (!username) return res.status(400).send('Username required');

  const user = { name: username };
  const accessToken = jwt.sign(user, ACCESS_TOKEN_SECRET, { expiresIn: '15m' });
  const refreshToken = jwt.sign(user, REFRESH_TOKEN_SECRET, { expiresIn: '7d' });

  refreshTokens.push(refreshToken);
  res.json({ accessToken, refreshToken });
});

// Route: Refresh Token (Issues new Access Token)
app.post('/refresh', (req, res) => {
  const { token } = req.body;
  if (!token) return res.sendStatus(401);
  if (!refreshTokens.includes(token)) return res.sendStatus(403);

  jwt.verify(token, REFRESH_TOKEN_SECRET, (err, user) => {
    if (err) return res.sendStatus(403);
    const accessToken = jwt.sign({ name: user.name }, ACCESS_TOKEN_SECRET, { expiresIn: '15m' });
    res.json({ accessToken });
  });
});

// Route: Logout (Deletes Refresh Token)
app.delete('/logout', (req, res) => {
  const { token } = req.body;
  refreshTokens = refreshTokens.filter(t => t !== token);
  res.sendStatus(204);
});

// Route: Protected

*   Goal: Express API.
    *   Features: JWT authentication, Refresh tokens, Rate limiting.
    *   Format: Short, complete JavaScript example + `npm install` command.

    *   Express (Framework)
    *   jsonwebtoken (JWT handling)
    *   express-rate-limit (Rate limiting)
    *   dotenv (Environment variables - though for a short example, I might hardcode secrets for simplicity, but it's better practice to mention them).

    *   *Setup:* Express app, middleware (json).
    *   *Rate Limiter:* Define a limiter for the auth routes.
    *   *Secrets:* `ACCESS_TOKEN_SECRET`, `REFRESH_TOKEN_SECRET`.
    *   *Storage:* A simple array/map for refresh tokens (since I can't set up a database in a single-file snippet).
    *   *Routes:*
        *   `/login`: Verify credentials $\rightarrow$ issue Access Token (short-lived) and Refresh Token (long-lived).
        *   `/token`: Accept Refresh Token $\rightarrow$ issue new Access Token.
        *   `/protected`: Middleware to verify Access Token $\rightarrow$ return protected data.
        *   `/logout`: Remove Refresh Token.

    *   *Rate Limiter:* Use `express-rate-limit`.
    *   *JWT:* `jwt.sign` and `jwt.verify`.
    *   *Middleware:* A function `authenticateToken` that checks the `Authorization` header.

    *   *Imports:* `express`, `jwt`, `rateLimit`.
    *   *Constants:* Tokens and secrets.
    *   *Logic:*
        *   Login: Hardcoded user for demo.
        *   Refresh: Validate refresh token against the "database" (array).
        *   Protected: Verify JWT.This is a complete, single-file implementation. In a production app, you would move the secrets to a `.env` file and the refresh tokens to a database (like Redis or MongoDB).

```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');

const app = express();
app.use(express.json());

const ACCESS_SECRET = 'access_secret_123';
const REFRESH_SECRET = 'refresh_secret_456';

// In-memory store for refresh tokens (Use Redis/DB in production)
let refreshTokens = [];

// 1. Rate Limiting: Max 100 requests per 15 minutes
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, 
  max: 100, 
  message: 'Too many requests, please try again later.'
});
app.use(limiter);

// Middleware to protect routes
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.sendStatus(401);

  jwt.verify(token, ACCESS_SECRET, (err, user) => {
    if (err) return res.status(403).json({ message: 'Token expired or invalid' });
    req.user = user;
    next();
  });
};

// Route: Login (Issue both tokens)
app.post('/login', (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ message: 'Username required' });

  const user = { name: username };

  const accessToken = jwt.sign(user, ACCESS_SECRET, { expiresIn: '15m' });
  const refreshToken = jwt.sign(user, REFRESH_SECRET, { expiresIn: '7d' });

  refreshTokens.push(refreshToken);
  res.json({ accessToken, refreshToken });
});

// Route: Refresh (Issue new access token using refresh token)
app.post('/token', (req, res) => {
  const { token } = req.body;
  if (!token) return res.sendStatus(401);
  if (!refreshTokens.includes(token)) return res.sendStatus(403);

  jwt.verify(token, REFRESH_SECRET, (err, user) => {
    if (err) return res.sendStatus(403);
    const accessToken = jwt.sign({ name: user.name }, ACCESS_SECRET, { expiresIn: '15m' });
    res.json({ accessToken });
  });
});

// Route: Logout (Invalidate refresh token)
app.delete('/logout', (req, res) => {
  const { token } = req.body;
  refreshTokens = refreshTokens.filter(t => t !== token);
  res.sendStatus(204);
});

// Route: Protected Resource
app.get('/protected', authenticateToken, (req, res) => {
  res.json({ message: `Hello ${req.user.name}, you have access to this data!` });
});

app.listen(3000, () => console.log('Server running on http://localhost:3000'));
```

