    *   Ensure `ETags` are captured (S3 returns them in the response header).To implement presigned multipart uploads, you need a three-step handshake: **Initiate**, **Upload Parts**, and **Complete**.

### Complete Example

#### 1. Server (`server.js`)
```javascript
const express = require('express');
const { S3Client, CreateMultipartUploadCommand, UploadPartCommand, CompleteMultipartUploadCommand } = require('@aws-sdk/client-s3');
const { getSignedUrl } = require('@aws-sdk/s3-request-presigner');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const s3 = new S3Client({ region: 'us-east-1', credentials: { accessKeyId: 'KEY', secretAccessKey: 'SECRET' }});
const BUCKET = 'your-bucket-name';

// Step 1: Start the upload process
app.post('/start', async (req, res) => {
    const { fileName } = req.body;
    const command = new CreateMultipartUploadCommand({ Bucket: BUCKET, Key: fileName });
    const { UploadId, Key } = await s3.send(command);
    res.json({ uploadId: UploadId, key: Key });
});

// Step 2: Get a presigned URL for a specific part
app.post('/sign-part', async (req, res) => {
    const { uploadId, key, partNumber } = req.body;
    const command = new UploadPartCommand({ Bucket: BUCKET, Key: key, UploadId: uploadId, PartNumber: partNumber });
    const url = await getSignedUrl(s3, command, { expiresIn: 3600 });
    res.json({ url });
});

// Step 3: Finalize the upload
app.post('/complete', async (req, res) => {
    const { uploadId, key, parts } = req.body; // parts = [{ ETag, PartNumber }, ...]
    const command = new CompleteMultipartUploadCommand({ 
        Bucket: BUCKET, Key: key, UploadId: uploadId, MultipartUpload: { Parts: parts } 
    });
    await s3.send(command);
    res.json({ success: true });
});

app.listen(3000, () => console.log('Server running on port 3000'));
```

