```javascript
'use client';
import { useState } from 'react';
import Fuse from 'fuse.js';

const DATA = [
  { title: 'Next.js Guide', text: 'Learn how to build modern web apps.' },
  { title: 'React Hooks', text: 'Deep dive into useEffect and useState.' },
  { title: 'Tailwind CSS', text: 'Utility-first CSS framework for rapid UI.' },
  { title: 'Node.js Tips', text: 'Optimize your backend performance.' },
];

export default function SearchPage() {
  const [query, setQuery] = useState('');

  // Configure Fuse.js
  const fuse = new Fuse(DATA, {
    keys: ['title', 'text'], // Fields to search in
    threshold: 0.3,         // 0.0 = perfect match, 1.0 = match anything
  });

  // Perform search
  const results = query 
    ? fuse.search(query).map(result => result.item) 
    : DATA;

  return (
    <div style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <h1>Local Full-Text Search</h1>
      <input
        type="text"
        placeholder="Search posts..."
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        style={{ padding: '0.5rem', width: '300px', marginBottom: '1rem', display: 'block' }}
      />
      <ul>
        {results.map((item, i) => (
          <li key={i} style={{ marginBottom: '1rem' }}>
            <strong>{item.title}</strong>: {item.text}
          </li>
        ))}
        {results.length === 0 && <p>No results found.</p>}
      </ul>
    </div>
  );
}
