```javascript
const Parser = require('rss-parser');
const parser = new Parser();

async function mergeFeeds(url1, url2) {
  try {
    // Fetch and parse both feeds concurrently
    const [feed1, feed2] = await Promise.all([
      parser.parseURL(url1),
      parser.parseURL(url2)
    ]);

    // Merge items into one array
    const combined = [...feed1.items, ...feed2.items];

    // Sort by date (descending - newest first)
    // rss-parser normalizes dates into 'pubDate' or 'isoDate'
    return combined.sort((a, b) => {
      const dateA = new Date(a.pubDate || a.isoDate);
      const dateB = new Date(b.pubDate || b.isoDate);
      return dateB - dateA;
    });
  } catch (error) {
    console.error('Error parsing feeds:', error);
  }
}

