```javascript
const puppeteer = require('puppeteer');
const pLimit = require('p-limit');

(async () => {
  const urls = Array.from({ length: 100 }, (_, i) => `https://example.com`); // Replace with your 100 URLs
  const limit = pLimit(10); // Process 10 concurrently
  const browser = await puppeteer.launch();

  const takeScreenshot = async (url, index) => {
    const page = await browser.newPage();
    try {
      await page.goto(url, { waitUntil: 'networkidle2', timeout: 30000 });
      await page.screenshot({ path: `screenshot-${index}.png`, fullPage: true });
      console.log(`✅ Saved ${index}: ${url}`);
    } catch (e) {
      console.error(`❌ Failed ${index} (${url}): ${e.message}`);
    } finally {
      await page.close();
    }
  };

  // Map URLs to limited promises
  const tasks = urls.map((url, i) => limit(() => takeScreenshot(url, i)));

  await Promise.all(tasks);
  await browser.close();
  console.log('All screenshots completed.');
})();
