const { PDFDocument } = require('pdf-lib');
const fs = require('fs');

async function fillAndMerge() {
    // 1. Load the PDF with the form and the PDF to merge
    const formPdfBytes = fs.readFileSync('form.pdf');
    const otherPdfBytes = fs.readFileSync('attachment.pdf');

    const pdfDoc = await PDFDocument.load(formPdfBytes);
    const otherPdfDoc = await PDFDocument.load(otherPdfBytes);

    // 2. Fill the form fields
    const form = pdfDoc.getForm();

    // Replace 'name_field' and 'date_field' with the actual IDs of your PDF fields
    form.getTextField('name_field').setText('John Doe');
    form.getTextField('date_field').setText('2023-10-27');

    // Make the form non-editable (flattening)
    form.flatten();

    // 3. Merge the other PDF
    // Copy all pages from the second PDF
    const copiedPages = await pdfDoc.copyPages(otherPdfDoc, otherPdfDoc.getPageIndices());

    // Append them to the end of the form PDF
    copiedPages.forEach((page) => pdfDoc.addPage(page));

    // 4. Save the final result
    const pdfBytes = await pdfDoc.save();
    fs.writeFileSync('output.pdf', pdfBytes);
    console.log('PDF created successfully!');
}

fillAndMerge().catch(err => console.log(err));
