const axios = require('axios');

/**
 * Validates Indian GSTIN format
 * Format: 2 digits (state), 10 chars (PAN), 1 digit (entity), 'Z', 1 char (checksum)
 */
const validateGSTIN = (gstin) => {
    const gstRegex = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/;
    return gstRegex.test(gstin);
};

/**
 * Validates Indian IFSC format
 * Format: 4 letters (bank), 0 (reserved), 6 alphanumeric (branch)
 */
const validateIFSC = (ifsc) => {
    const ifscRegex = /^[A-Z]{4}0[A-Z0-9]{6}$/;
    return ifscRegex.test(ifsc);
};

/**
 * Looks up bank details using the Razorpay IFSC API
 */
const lookupBankBranch = async (ifsc) => {
    try {
        const response = await axios.get(`https://ifsc.razorpay.com/${ifsc}`);
        return response.data;
    } catch (error) {
        throw new Error(error.response?.status === 404 ? 'Invalid IFSC code' : 'API Error');
    }
};

