        const Docker = require('dockerode');
        const axios = require('axios');

        const docker = new Docker();
        const SLACK_WEBHOOK_URL = 'YOUR_SLACK_WEBHOOK_URL';
        const CONTAINER_NAME = 'your_container_name';

        async function tailLogs() {
            const container = docker.getContainer(CONTAINER_NAME);
            const logStream = await container.logs({
                follow: true,
                stdout: true,
                stderr: true,
                tail: 0
            });

            logStream.on('data', (chunk) => {
                const logLine = chunk.toString('utf8');
                if (logLine.toLowerCase().includes('error')) {
                    axios.post(SLACK_WEBHOOK_URL, {
                        text: `🚨 *Error detected in ${CONTAINER_NAME}*:\n\`\`\`${logLine}\`\`\``
                    }).catch(err => console.error('Slack Error:', err.message));
                }
            });
        }

        tailLogs().catch(console.error);
