    *   *Formatting:* A simple `console.log` table or list. `console.table` is great for CLI output.

    *   Code block.
    *   Install command.```javascript
const k8s = require('@kubernetes/client-node');

async function listPodRestarts() {
  const kc = new k8s.KubeConfig();
  kc.loadFromDefault();

  const k8sApi = kc.makeApiClient(k8s.CoreV1Api);

  try {
    const res = await k8sApi.listPodForAllNamespaces();
    const pods = res.body.items;

    const podStats = pods.map(pod => {
      // Sum restarts across all containers in the pod
      const totalRestarts = pod.status.containerStatuses 
        ? pod.status.containerStatuses.reduce((sum, status) => sum + status.restartCount, 0) 
        : 0;

      return {
        Namespace: pod.metadata.namespace,
        Pod: pod.metadata.name,
        Restarts: totalRestarts
      };
    });

    console.table(podStats);
  } catch (err) {
    console.error('Error fetching pods:', err);
  }
}

listPodRestarts();
