```javascript
const { execSync } = require('child_process');
const { globSync } = require('glob');
const { Octokit } = require('@octokit/rest');

// Configuration
const GITHUB_TOKEN = 'your_personal_access_token';
const REPO_OWNER = 'your_username';
const REPO_NAME = 'your_repo';

const octokit = new Octokit({ auth: GITHUB_TOKEN });

async function checkDependencies() {
  const packageJsons = globSync('**/package.json', { ignore: '**/node_modules/**' });
  let report = '## ⚠️ Dependency Report\n\n';
  let issuesFound = false;

  for (const pkgPath of packageJsons) {
    const dir = pkgPath.replace('/package.json', '');
    console.log(`Checking ${dir}...`);

    try {
      // npm outdated returns exit code 1 if outdated packages exist
      const outdated = execSync(`npm outdated --json`, { cwd: dir, encoding: 'utf8' });
      if (outdated) {
        report += `### 📦 Outdated in ${dir}\n\`\`\`json\n${outdated}\n\`\`\`\n\n`;
        issuesFound = true;
      }
    } catch (e) {
      if (e.stdout) {
        report += `### 📦 Outdated in ${dir}\n\`\`\`json\n${e.stdout}\n\`\`\`\n\n`;
        issuesFound = true;
      }
    }

    try {
      // npm audit returns exit code 1 if vulnerabilities exist
      const audit = execSync(`npm audit --json`, { cwd: dir, encoding: 'utf8' });
      if (audit) {
        report += `### 🛡️ Vulnerabilities in ${dir}\n\`\`\`json\n${audit}\n\`\`\`\n\n`;
        issuesFound = true;
      }
    } catch (e) {
      if (e.stdout) {
        report += `### 🛡️ Vulnerabilities in ${dir}\n\`\`\`json\n${e.stdout}\n\`\`\`\n\n`;
        issuesFound = true;
      }
    }
  }

  if (issuesFound) {
    await octokit.rest.issues.create({
      owner: REPO_OWNER,
      repo: REPO_NAME,
      title: '🚨 Outdated and Vulnerable Dependencies',
      body: report,
    });
    console.log('GitHub issue created successfully.');
  } else {
    console.log('No issues found!');
  }
}

checkDependencies().catch(console.error);
```

