    *   *Step 1: Scheduling.* Use `node-cron` with `0 0 * * *` (midnight).
    *   *Step 2: Backup.* Execute `mongodump --archive=backup.gz --gzip`.
    *   *Step 3: Upload.* Use `PutObjectCommand` from AWS SDK v3.
    *   *Step 4: Cleanup.* Delete the local backup file.

    *   *Environment Variables:* I must use placeholders for credentials (MONGO_URI, AWS_ACCESS_KEY, etc.) to make the code professional and secure.
    *   *Error Handling:* Basic try-catch blocks.

    *   *Wait, `mongodump` is not a Node package.* I need to mention that `mongodump` must be installed on the system (MongoDB Database Tools).
    *   *AWS SDK:* Use the modern v3 SDK.

    *   Import `cron`, `exec` (from `child_process`), `fs`, and `S3Client`.
    *   Configure S3 client.
    *   Define the cron schedule.
    *   The logic:
        1. Generate filename (timestamp).
        2. Run `mongodump`.
        3. Read file.
        4. Upload to S3.
        5. Delete local file.To run this, you must have the **MongoDB Database Tools** (specifically `mongodump`) installed on your server/machine.

```javascript
const cron = require('node-cron');
const { exec } = require('child_process');
const fs = require('fs');
const { S3Client, PutObjectCommand } = require('@aws-sdk/client-s3');

// Configuration
const CONFIG = {
  mongoUri: 'mongodb://localhost:27017/myDatabase',
  s3Bucket: 'my-backup-bucket',
  awsRegion: 'us-east-1',
  backupFileName: 'dump.gz'
};

const s3Client = new S3Client({ region: CONFIG.awsRegion });

async function backupAndUpload() {
  console.log('Starting backup...');

  // 1. Create a compressed MongoDB dump to a local file
  const dumpCmd = `mongodump --uri="${CONFIG.mongoUri}" --archive=${CONFIG.backupFileName} --gzip`;

  exec(dumpCmd, async (error) => {
    if (error) {
      console.error('Mongodump failed:', error);
      return;
    }

    try {
      // 2. Upload the file to S3
      const fileStream = fs.createReadStream(CONFIG.backupFileName);
      const uploadParams = {
        Bucket: CONFIG.s3Bucket,
        Key: `backups/backup-${new Date().toISOString().split('T')[0]}.gz`,
        Body: fileStream,
      };

      await s3Client.send(new PutObjectCommand(uploadParams));
      console.log('Backup uploaded to S3 successfully.');

      // 3. Clean up local file
      fs.unlinkSync(CONFIG.backupFileName);
    } catch (err) {
      console.error('S3 Upload failed:', err);
    }
  });
}

// Schedule: Every night at midnight (0 0 * * *)
cron.schedule('0 0 * * *', () => {
  backupAndUpload();
});

console.log('Backup cron job initialized...');
```

