    let absoluteTime = 0;

    track.forEach(event => {
        // MIDI events use delta-time (time since the last event)
        // We add it to absoluteTime to get the actual timestamp
        absoluteTime += event.deltaTime;

        // Filter for Note On events with a velocity > 0
        if (event.type === 'noteOn' && event.velocity > 0) {
            console.log(`Track ${trackIndex} | Note: ${event.note} | Time: ${absoluteTime} | Velocity: ${event.velocity}`);
        }
    });
});
