const Gpio = require('onoff').Gpio;

// Setup pins (using BCM numbering)
const led = new Gpio(17, 'out');      // LED connected to GPIO 17
const button = new Gpio(27, 'in', 'both'); // Button connected to GPIO 27

console.log('Blinking LED on pin 17. Press button on pin 27...');

// 1. Blink the LED every 500ms
setInterval(() => {
  led.write(led.read() === '0' ? '1' : '0');
}, 500);

// 2. Read the Button
