### Example Code

```javascript
const noble = require('@nodable/noble');

// The standard GATT UUIDs for Battery Service and Battery Level
const BATTERY_SERVICE_UUID = '180f';
const BATTERY_LEVEL_CHAR_UUID = '2a19';

async function readBattery() {
  await noble.init();

  noble.on('stateChange', async (state) => {
    if (state !== 'poweredOn') return;

    console.log('Scanning for battery devices...');
    // Scan specifically for devices advertising the Battery Service
    await noble.startScanningAsync([new noble.Service({ uuid: BATTERY_SERVICE_UUID })], false);
  });

  noble.on('discover', async (peripheral) => {
    console.log(`Found device: ${peripheral.advertisement.localName || 'Unknown'}`);
    await noble.stopScanningAsync();

    try {
      await peripheral.connectAsync();
      console.log('Connected!');

      // Discover the battery characteristic
      const { characteristics } = await peripheral.discoverSomeServicesAndCharacteristicsAsync([BATTERY_SERVICE_UUID], [BATTERY_LEVEL_CHAR_UUID]);
      const batteryChar = characteristics.find(c => c.uuid === BATTERY_LEVEL_CHAR_UUID);

      if (batteryChar) {
        const data = await batteryChar.readValueAsync();
        console.log(`Battery Level: ${data[0]}%`);
      } else {
        console.log('Battery characteristic not found.');
      }

      await peripheral.disconnectAsync();
      process.exit();
    } catch (err) {
      console.error('Error:', err);
      process.exit(1);
    }
  });
}

readBattery();
```

