        });
        ```

    *   Ensure the code is clean and runnable.
    *   Include a sample ticker.
    *   Make sure the `npm install` command is precise.To achieve this, the most reliable open-source library is `yahoo-finance2`, as it provides access to historical data for NSE tickers (which require the `.NS` suffix).

### The Code (`index.js`)

```javascript
const yahooFinance = require('yahoo-finance2').default;

async function getSMA(ticker, windowSize = 50) {
  try {
    // Fetch historical data for the last year to ensure we have enough for the window
    const queryOptions = { period1: '2023-01-01', interval: '1d' };
    const result = await yahooFinance.historical(ticker, queryOptions);

    const closes = result.map(day => day.close);

    // Compute Simple Moving Average (SMA)
    const sma = closes.map((val, index, arr) => {
      if (index < windowSize - 1) return null; // Not enough data yet
      const slice = arr.slice(index - windowSize + 1, index + 1);
      const sum = slice.reduce((a, b) => a + b, 0);
      return (sum / windowSize).toFixed(2);
    });

    // Get the most recent closing price and its 50-day SMA
    const lastPrice = closes[closes.length - 1];
    const lastSMA = sma[sma.length - 1];

    console.log(`Ticker: ${ticker}`);
    console.log(`Current Close: ${lastPrice.toFixed(2)}`);
    console.log(`${windowSize}-Day SMA: ${lastSMA}`);
  } catch (error) {
    console.error('Error fetching data:', error);
  }
}

// Use .NS suffix for National Stock Exchange of India
getSMA('RELIANCE.NS'); 
```

